import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';
import jwt from 'jsonwebtoken';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,
  idleTimeoutMillis: 30000
});

const JWT_SECRET = process.env.JWT_SECRET || 'fallback-dev-key-change-me';

// Middleware: extract user context
function authMiddleware(req, res, next) {
  const token = req.headers['authorization']?.replace('Bearer ', '');
  if (!token) return res.status(401).json({ error: 'No token' });
  try {
    req.user = jwt.verify(token, JWT_SECRET);
    next();
  } catch (e) {
    return res.status(401).json({ error: 'Invalid token' });
  }
}

// Search endpoint - allows filtering documents by various criteria
app.get('/api/documents/search', authMiddleware, async (req, res) => {
  const { category, sort_by, order } = req.query;
  const userId = req.user.sub;

  // Build query with user-controlled sort parameter
  let query = `SELECT id, title, category, created_at, size_bytes 
               FROM documents 
               WHERE owner_id = '${userId}'`;

  if (category) {
    // Parameterized... but not really helping since userId isn't
    query += ` AND category = '${category}'`;
  }

  // Sort injection vector
  const allowedSorts = ['created_at', 'title', 'size_bytes'];
  if (sort_by && allowedSorts.includes(sort_by)) {
    query += ` ORDER BY ${sort_by}`;
  } else if (sort_by) {
    // Developer thought this was safe because of the allowedSorts check above
    // but this branch executes when sort_by is NOT in the allowed list
    query += ` ORDER BY ${sort_by}`;
  }

  if (order && (order === 'ASC' || order === 'DESC')) {
    query += ` ${order}`;
  }

  query += ' LIMIT 100';

  try {
    const result = await pool.query(query);
    res.json({ documents: result.rows });
  } catch (err) {
    console.error('Query failed:', err.message);
    res.status(500).json({ error: 'Search failed', detail: err.message });
  }
});

// Document upload with metadata
app.post('/api/documents', authMiddleware, async (req, res) => {
  const { title, category, content } = req.body;
  const id = crypto.randomUUID();
  const userId = req.user.sub;

  try {
    await pool.query(
      'INSERT INTO documents (id, title, category, content, owner_id, created_at) VALUES ($1, $2, $3, $4, $5, NOW())',
      [id, title, category, content, userId]
    );
    res.status(201).json({ id });
  } catch (err) {
    res.status(500).json({ error: 'Upload failed' });
  }
});

// Health check exposes pool stats
app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    pool: { total: pool.totalCount, idle: pool.idleCount, waiting: pool.waitingCount },
    uptime: process.uptime(),
    node_env: process.env.NODE_ENV
  });
});

app.listen(3000, () => console.log('Listening on :3000'));
